:root {
  --bg-card: #0f1521;
  --bg-header: #1a2540;
  --bg-poster: #0d1f3c;
  --bg-tag: #1e3a5f;
  --bg-seat: #151e30;
  --accent-gold: #f5c842;
  --accent-teal: #38c9b0;
  --accent-pink: #e84393;
  --accent-star: #ffffff;
  --text-primary: #eef2ff;
  --text-secondary: #8899bb;
  --text-caption: #38c9b0;
  --border-subtle: #2a3a5c;
  --planet-color: #e84393;
  --horizon-color: #f5c842;
  --bar-color: #eef2ff;
  --rating-bg: #e84393;
}

.cinema-card {
  width: 480px;
  background: var(--bg-card);
  border-radius: 16px;
  overflow: hidden;
  border: 1px solid var(--border-subtle);
  font-size: 13px;
}

.card-header {
  background: var(--bg-header);
  padding: 14px 16px 12px;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  border-bottom: 1px solid var(--border-subtle);
}

.header-left {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.venue-label {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 2px;
  color: var(--accent-teal);
  text-transform: uppercase;
}

.movie-title {
  font-size: 22px;
  font-weight: 800;
  color: var(--text-primary);
  margin: 0;
  line-height: 1.1;
}

.tagline {
  font-size: 12px;
  color: var(--text-secondary);
  margin: 0;
}

.rating-badge {
  display: flex;
  align-items: flex-end;
  background: var(--rating-bg);
  border-radius: 6px;
  padding: 4px 7px;
  line-height: 1;
}

.rating-value {
  font-size: 14px;
  font-weight: 800;
  color: var(--text-primary);
}

.rating-13 {
  font-size: 9px;
  font-weight: 700;
  color: var(--text-primary);
  margin-bottom: 1px;
}

.card-body {
  display: flex;
  gap: 0;
}

.poster-block {
  width: 130px;
  flex-shrink: 0;
  padding: 14px 12px 14px 14px;
  border-right: 1px dashed var(--border-subtle);
}

.poster {
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.poster-art {
  width: 104px;
  height: 140px;
  background: var(--bg-poster);
  border-radius: 8px;
  border: 1px solid var(--border-subtle);
  position: relative;
  overflow: hidden;
}

.star {
  position: absolute;
  background: var(--accent-star);
  border-radius: 50%;
}

.star-1 {
  width: 3px;
  height: 3px;
  top: 18px;
  left: 20px;
}

.star-2 {
  width: 2px;
  height: 2px;
  top: 35px;
  left: 65px;
}

.star-3 {
  width: 3px;
  height: 3px;
  top: 52px;
  right: 18px;
}

.planet {
  position: absolute;
  width: 38px;
  height: 38px;
  background: var(--planet-color);
  border-radius: 50%;
  top: 50px;
  left: 50%;
  transform: translateX(-50%);
  border: 3px solid var(--accent-gold);
}

.horizon-line {
  position: absolute;
  bottom: 24px;
  left: 0;
  right: 0;
  height: 3px;
  background: var(--horizon-color);
  opacity: 0.6;
  border-radius: 2px;
}

.poster-caption {
  font-size: 11px;
  font-weight: 700;
  color: var(--text-caption);
  text-align: center;
  letter-spacing: 2px;
}

.info-block {
  flex: 1;
  padding: 14px 14px 14px 12px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.meta-row {
  display: flex;
  gap: 10px;
}

.meta-item {
  display: flex;
  flex-direction: column;
  gap: 2px;
  flex: 1;
}

.meta-label {
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 1px;
  color: var(--text-secondary);
  text-transform: uppercase;
}

.meta-value {
  font-size: 13px;
  font-weight: 700;
  color: var(--text-primary);
}

.genre-tags {
  display: flex;
  gap: 6px;
}

.tag {
  background: var(--bg-tag);
  color: var(--accent-teal);
  font-size: 11px;
  font-weight: 700;
  padding: 3px 9px;
  border-radius: 20px;
  border: 1px solid var(--accent-teal);
  letter-spacing: 0.5px;
}

.seat-row {
  display: flex;
  gap: 0;
  background: var(--bg-seat);
  border-radius: 8px;
  overflow: hidden;
  border: 1px solid var(--border-subtle);
}

.seat-info {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 7px 4px;
  gap: 2px;
  border-right: 1px solid var(--border-subtle);
}

.seat-info:last-child {
  border-right: none;
}

.seat-label {
  font-size: 9px;
  font-weight: 600;
  color: var(--text-secondary);
  text-transform: uppercase;
  letter-spacing: 1px;
}

.seat-value {
  font-size: 14px;
  font-weight: 800;
  color: var(--accent-gold);
}

.ticket-footer {
  display: flex;
  flex-direction: column;
  gap: 4px;
  border-top: 1px dashed var(--border-subtle);
  padding-top: 8px;
}

.barcode {
  display: flex;
  gap: 2px;
  align-items: stretch;
  height: 24px;
}

.bar {
  background: var(--bar-color);
  width: 4px;
  border-radius: 1px;
  flex-shrink: 0;
}

.bar.thin {
  width: 2px;
}

.bar.thick {
  width: 6px;
}

.ticket-num {
  font-size: 10px;
  color: var(--text-secondary);
  letter-spacing: 1px;
  font-weight: 600;
}
